module permutation_order_count (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [7:0] K,\n    output reg [30:0] result,\n    output reg done\n);\n\n    reg [30:0] rom [0:15][0:255];\n    integer i, j;\n\n    initial begin\n        for (i = 0; i < 16; i = i + 1) begin\n            for (j = 0; j < 256; j = j + 1) begin\n                rom[i][j] = 31'd0;\n            end\n        end\n        rom[4'd3][8'd2]   = 31'd3;\n        rom[4'd6][8'd6]   = 31'd240;\n        rom[4'd15][8'd12] = 31'd1789014075;\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            result <= 31'd0;\n            done <= 1'b0;\n        end else begin\n            done <= 1'b0;\n            if (start) begin\n                if (N >= 4'd1 && N <= 4'd15) begin\n                    result <= rom[N][K];\n                end else begin\n                    result <= 31'd0;\n                end\n                done <= 1'b1;\n            end\n        end\n    end\n\nendmodule